func (*ConcCstVisitCstVisitList) isCstVisitList() {}

func (t *ConcCstVisitCstVisitList) Hash() uint32 { return t.hash }

func (t *ConcCstVisitCstVisitList) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*ConcCstVisitCstVisitList)
	if !ok {
		return false
	}
	if len(t.Slots) != len(o.Slots) {
		return false
	}
	for i := range t.Slots {
		if t.Slots[i] != o.Slots[i] {
			return false
		}
	}
	return true
}

func (t *ConcCstVisitCstVisitList) Duplicate() sharedobjects.Term {
	cp := append([]CstVisit(nil), t.Slots...)
	return &ConcCstVisitCstVisitList{Slots: cp, hash: t.hash}
}

func (t *ConcCstVisitCstVisitList) String() string {
	parts := make([]string, len(t.Slots))
	for i, v := range t.Slots {
		parts[i] = fmt.Sprintf("%v", v)
	}
	return "ConcCstVisit" + "(" + strings.Join(parts, ",") + ")"
}

// MakeConcCstVisit builds the canonical (shared) ConcCstVisit term.
func MakeConcCstVisit(args ...CstVisit) CstVisitList {
	hashes := make([]uint32, 0, len(args))
	for _, a := range args {
		hashes = append(hashes, a.Hash())
	}
	proto := &ConcCstVisitCstVisitList{Slots: args, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("ConcCstVisit"), hashes)}
	return factory.Build(proto).(*ConcCstVisitCstVisitList)
}
